// StatisticsTests — feature 173 (A24-P01) T-A24-107 (FR-A24-103, FR-A24-104; clarification Q2). The nearest-rank rule
// on small sets, the minimum counts, the flag order, and the 20,000-sample set generated by a stated rule whose
// percentiles follow from the rule itself (no committed JSON for it).
import Foundation
import Testing
import GraphicsBenchmarkLabCore

@Suite struct StatisticsTests {
    /// 1, 2, … n as doubles, ascending.
    private func ascending(_ n: Int) -> [Double] {
        var values: [Double] = []
        for k in 1...n { values.append(Double(k)) }
        return values
    }

    @Test func nearestRankOnSmallSets() {
        let empty = Percentiles.nearestRank(50, of: [])
        #expect(empty == nil)
        let one = Percentiles.nearestRank(50, of: [7.5])
        #expect(one == 7.5)
        // n = 3: rank (50 · 3 + 99) / 100 = 2.
        let three = Percentiles.nearestRank(50, of: [1, 2, 3])
        #expect(three == 2)
        // n = 4: rank (200 + 99) / 100 = 2, the lower middle (no interpolation).
        let four = Percentiles.nearestRank(50, of: [1, 2, 3, 4])
        #expect(four == 2)
        // n = 20: p95 rank (1,900 + 99) / 100 = 19.
        let twenty = Percentiles.nearestRank(95, of: ascending(20))
        #expect(twenty == 19)
        // n = 100: p99 rank 99, p95 rank 95, p50 rank 50.
        let hundred = ascending(100)
        let p99 = Percentiles.nearestRank(99, of: hundred)
        let p95 = Percentiles.nearestRank(95, of: hundred)
        let p50 = Percentiles.nearestRank(50, of: hundred)
        #expect(p99 == 99)
        #expect(p95 == 95)
        #expect(p50 == 50)
        // n = 101: ⌈50.5⌉ = 51, ⌈95.95⌉ = 96, ⌈99.99⌉ = 100.
        let hundredOne = ascending(101)
        let q50 = Percentiles.nearestRank(50, of: hundredOne)
        let q95 = Percentiles.nearestRank(95, of: hundredOne)
        let q99 = Percentiles.nearestRank(99, of: hundredOne)
        #expect(q50 == 51)
        #expect(q95 == 96)
        #expect(q99 == 100)
        // An unsupported percentile has no value.
        let p90 = Percentiles.nearestRank(90, of: hundred)
        #expect(p90 == nil)
    }

    @Test func minimumCounts() {
        let minimums = Percentiles.minimumCount
        #expect(minimums == [50: 1, 95: 20, 99: 100])
        for (p, minimum) in minimums {
            let below = Percentiles.nearestRank(p, of: ascending(max(minimum - 1, 1)))
            let at = Percentiles.nearestRank(p, of: ascending(minimum))
            if minimum > 1 { #expect(below == nil, "p\(p) below \(minimum)") }
            #expect(at != nil, "p\(p) at \(minimum)")
        }
    }

    @Test func distributionSortsItsValues() {
        let distribution = Distribution.make([3, 1, 2])
        let expected = Distribution(p50: 2, p95: nil, p99: nil, count: 3)
        #expect(distribution == expected)
        let empty = Distribution.make([])
        #expect(empty == Distribution(p50: nil, p95: nil, p99: nil, count: 0))
    }

    @Test func flagsAreOrderedByRawValueAndStoredUnique() {
        let order: [QualityFlag] = [.tooFewForP99, .noSamples, .gpuTimeNotAvailable, .tooFewForP95, .droppedFrames]
        let sorted = order.sorted()
        #expect(sorted == [.droppedFrames, .gpuTimeNotAvailable, .noSamples, .tooFewForP95, .tooFewForP99])
        let distribution = Distribution(p50: nil, p95: nil, p99: nil, count: 0)
        let summary = Summary(interval: distribution, cpu: distribution, gpu: nil, measured: 0, warmUpExcluded: 0,
                              coolDownExcluded: 0, dropped: 0, flags: [.noSamples, .droppedFrames, .noSamples])
        let flags = summary.flags
        #expect(flags == [.droppedFrames, .noSamples])
    }

    /// The rule set of T-A24-107: 20,000 measured frames k = 0 … 19,999 with interval = CPU = 1 + (k mod 1,000) / 100
    /// ms and no GPU time.
    ///
    /// Derivation: each residue r = k mod 1,000 (0 … 999) occurs exactly 20 times, and the value grows with r, so
    /// sorted ascending the ranks 20·r + 1 … 20·r + 20 all hold 1 + r / 100. With n = 20,000:
    /// - p50: rank (50 · 20,000 + 99) / 100 = 10,000, r = (10,000 − 1) / 20 = 499, value 1 + 499 / 100 = 5.99;
    /// - p95: rank 19,000, r = 18,999 / 20 = 949, value 10.49;
    /// - p99: rank 19,800, r = 19,799 / 20 = 989, value 10.89.
    /// The expected values are formed by the same expression as the samples, so equality is exact.
    @Test func twentyThousandSamplesFollowTheRule() throws {
        let n = 20_000
        var samples: [FrameSample] = []
        samples.reserveCapacity(n)
        for k in 0..<n {
            let value = 1 + Double(k % 1_000) / 100
            samples.append(FrameSample(frameIndex: k, phase: .measure, intervalMs: value, cpuMs: value, gpuMs: nil,
                                       dropped: false))
        }
        let value: (Int) -> Double = { r in 1 + Double(r) / 100 }
        let expectedDistribution = Distribution(p50: value(499), p95: value(949), p99: value(989), count: n)
        let summary = try Summary.make(samples)
        let interval = summary.interval
        let cpu = summary.cpu
        #expect(interval == expectedDistribution)
        #expect(cpu == expectedDistribution)
        #expect(summary.gpu == nil)
        #expect(summary.measured == n)
        #expect(summary.flags == [.gpuTimeNotAvailable])
        let p50 = interval.p50 ?? .nan
        let p95 = interval.p95 ?? .nan
        let p99 = interval.p99 ?? .nan
        #expect(abs(p50 - 5.99) < 1e-9)
        #expect(abs(p95 - 10.49) < 1e-9)
        #expect(abs(p99 - 10.89) < 1e-9)
    }
}
